/* @lc app=leetcode id=1964 lang=kotlin */ class Solution { fun longestObstacleCourseAtEachPosition(obstacles: IntArray): IntArray = IntArray(obstacles.size).let { ans -> IntArray(obstacles.size).let { dp -> DeepRecursiveFunction<Triple<Int, Int, Int>, Int> { (l, r, x) -> if (l >= r) l else ((l + r) ushr 1).let { mid -> callRecursive(if (dp[mid] <= x) Triple(mid + 1, r, x) else Triple(l, mid, x)) } }.let { search -> obstacles.indices.fold(0) { len, i -> search(Triple(0, len, obstacles[i])).let { l -> obstacles[i].also { dp[l] = it }.also { ans[i] = l + 1 }.let { if (l == len) len + 1 else len } } }.let { ans } } } } }